def split_words(text: str) -> list[str]:
    words: list[str] = []
    current: list[str] = []
    word_started = False
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if ch == " " or ch == "\t" or ch == "\n":
            i += 1
            if word_started:
                words.append("".join(current))
                current.clear()
                word_started = False
            continue

        if ch == "#":
            if not word_started:
                i += 1
                while i < n and text[i] != "\n":
                    i += 1
            else:
                current.append(ch)
                word_started = True
                i += 1
            continue

        if ch == "'":
            i += 1
            word_started = True

            while i < n and text[i] != "'":
                current.append(text[i])
                i += 1

            if i == n:
                raise ValueError("unterminated single quote")

            i += 1
            continue

        if ch == '"':
            i += 1
            word_started = True
            closed = False

            while i < n:
                c = text[i]

                if c == '"':
                    i += 1
                    closed = True
                    break

                if c == "\\":
                    if i + 1 == n:
                        raise ValueError("backslash at end of string")

                    nxt = text[i + 1]

                    if nxt in ('"', "\\", "$", "`"):
                        current.append(nxt)
                        i += 2
                    elif nxt == "\n":
                        i += 2
                    else:
                        current.append("\\")
                        i += 1
                else:
                    current.append(c)
                    i += 1

            if not closed:
                raise ValueError("unterminated double quote")

            continue

        current.append(ch)
        word_started = True
        i += 1

    if word_started:
        words.append("".join(current))

    return words
